import { describe, it, expect } from 'vitest'
import { shapesOf, identicalShapes, subsets, inversePairs, POLARITY_CANDIDATES } from './index'

/**
 * Measured against the LIVE config (payload-types is generated BY Payload — the shapes it actually booted).
 * Not fixtures: the finding IS the live tree, and a fixture would only prove the algorithm.
 */
describe('collapse — what can honestly become one table', () => {
  it('reads every booted collection from the generated types', () => {
    const s = shapesOf()
    expect(s.length).toBeGreaterThan(200)
    expect(s.map((x) => x.slug)).toContain('gl-postings')
  })

  // THE REFUTATION OF THE TELOS. "Collapse ~200 collections to a dense core" implies redundancy.
  // Content-addressing says there is none: 231 genuinely distinct shapes, zero duplicates.
  it('NO two collections are the same table — structural headroom is zero', () => {
    expect(identicalShapes()).toHaveLength(0)
  })

  it('the shape address is a theorem — same fields+types ⇒ same uuid', () => {
    const s = shapesOf()
    const uniq = new Set(s.map((x) => x.uuid))
    expect(uniq.size).toBe(s.length) // 231 distinct shapes ⇒ 231 distinct addresses
    expect(s[0]!.uuid).toHaveLength(36)
  })

  // THE ONE REAL MERGE, and it is exact: not "similar", not "both are parties" — one field.
  it('customers ⊂ vendors, differing by exactly `bank` — the only semantically real subset', () => {
    const party = subsets().find((s) => s.slug === 'customers' && s.host === 'vendors')
    expect(party).toBeDefined()
    expect(party!.extra).toEqual(['bank'])
  })

  // THE BOUNDARY, asserted rather than promised. Set inclusion is DECIDABLE and decides the WRONG question:
  // a small table fits inside almost anything. This is where "trust only theorems" stops — a theorem cannot
  // tell you what two tables MEAN.
  it('fitting is NOT sameness — the tool proposes absurd merges, and must be read by a human', () => {
    const all = subsets()
    const absurd = all.find((s) => s.slug === 'payload-migrations')
    expect(absurd).toBeDefined() // Payload's OWN migration table "fits" inside a manufacturing table
    expect(absurd!.extra.length).toBeGreaterThan(20) // 22 fields apart: fitting, and meaning nothing
    // the real one sorts FIRST: fewest extra fields = closest to sameness
    expect(all[0]!.slug).toBe('customers')
  })

  // THE INVERSE-POLARITY LENS — held as a conjecture ("the collections fold in inverted pairs"), then measured.
  // The dream named 21; reality names the count below. The theorem refutes not only the dream but the EYE: a
  // pair named an antonym by meaning is not thereby a merge — the real shapes decide, and mostly they say no.
  describe('inverse pairs — meaning proposes, shape decides', () => {
    it('the declared candidates are a transparent human judgement, never inferred', () => {
      // the map is written in the open (like rules/audience) so it can be argued with — not a measurement.
      expect(POLARITY_CANDIDATES.length).toBeGreaterThan(0)
      expect(POLARITY_CANDIDATES.map((p) => `${p[0]}↔${p[1]}`)).toContain('customers↔vendors')
    })

    it('customers ↔ vendors is the ONLY declared pair whose shapes collapse (verdict theorem)', () => {
      const pairs = inversePairs()
      const theorem = pairs.filter((p) => p.verdict === 'theorem')
      expect(theorem).toHaveLength(1)
      expect(theorem[0]!.a).toBe('customers')
      expect(theorem[0]!.b).toBe('vendors')
      expect(theorem[0]!.jaccard).toBeGreaterThanOrEqual(0.6)
    })

    // THE EYE REFUTED. I named these clean inverse pairs; the shapes share almost nothing — two tables that
    // only rhyme. Naming a pair by meaning is exactly the harmonic over-reach the theorem exists to catch.
    it('payments ↔ receipts and sales ↔ returns are DISTINCT — antonyms are not merges', () => {
      const pairs = inversePairs()
      const pr = pairs.find((p) => p.a === 'payments' && p.b === 'receipts')!
      const sr = pairs.find((p) => p.a === 'sales' && p.b === 'returns')!
      expect(pr.verdict).toBe('distinct')
      expect(sr.verdict).toBe('distinct')
      expect(pr.jaccard).toBeLessThan(0.3)
    })

    it('the count is what reality says, not what the dream said — far from 21', () => {
      const pairs = inversePairs()
      // the conjecture "231 fold into a 21-cross cube" made contact and was answered: a handful, one provable.
      expect(pairs.length).toBeLessThan(21)
      expect(pairs.every((p) => p.verdict !== 'absent')).toBe(true) // every declared slug is a real collection
    })
  })
})
